const items = $input.all();
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) {
  staticData.rateLimits = {};
}

const now = Date.now();
const windowMs = 60 * 1000; // 60 seconds
const maxRequests = 5;
const results = [];

for (const item of items) {
  const msg = item.json.message || item.json.edited_message || {};
  const chatId = msg.chat?.id ?? null;
  const userId = String(msg.from?.id ?? 'unknown');
  const username = msg.from?.username ? `@${msg.from.username}` : 'no_username';
  const fullName = [msg.from?.first_name, msg.from?.last_name].filter(Boolean).join(' ') || 'Unknown User';
  const rawText = typeof msg.text === 'string' ? msg.text.trim() : '';
  const timestamp = msg.date
    ? new Date(msg.date * 1000).toISOString()
    : new Date().toISOString();

  // 1. Check per-user rate limit (max 5 messages per 60s)
  const recentTimestamps = (staticData.rateLimits[userId] || []).filter(ts => now - ts < windowMs);
  let isRateLimited = false;

  if (recentTimestamps.length >= maxRequests) {
    isRateLimited = true;
    staticData.rateLimits[userId] = recentTimestamps;
  } else {
    recentTimestamps.push(now);
    staticData.rateLimits[userId] = recentTimestamps;
  }

  // 2. Check /history command & basic text validity
  const isHistoryCmd = /^\/history(@\w+)?$/i.test(rawText);
  const isValid = Boolean(chatId && rawText.length > 0);

  results.push({
    json: {
      chat_id: chatId,
      user_id: userId,
      username,
      full_name: fullName,
      text: rawText,
      timestamp,
      is_rate_limited: isRateLimited,
      is_history_cmd: isHistoryCmd,
      is_valid: isValid,
      error_reason: isValid ? '' : 'Empty or non-text message (photo/sticker)'
    }
  });
}

return results;

