const allowedCategories = ['billing', 'technical', 'weather', 'general'];
const allowedLanguages = ['az', 'en', 'ru'];
const inputMeta = $('Extract & Validate Input').item.json;
const rawContent = $input.item.json?.message?.content ?? '';

let parsedCategory = 'unknown';
let parsedLanguage = 'en';
let parseError = '';

try {
  const cleaned = rawContent
    .replace(/<\|channel>thought[\s\S]*?<channel\|>/g, '')
    .replace(/```json\s*/gi, '')
    .replace(/```/g, '')
    .trim();

  const parsed = JSON.parse(cleaned);
  const candidateCat = String(parsed.category || '').toLowerCase().trim();
  const candidateLang = String(parsed.language || '').toLowerCase().trim();

  if (allowedLanguages.includes(candidateLang)) {
    parsedLanguage = candidateLang;
  }

  if (allowedCategories.includes(candidateCat)) {
    parsedCategory = candidateCat;
  } else {
    parseError = `Disallowed or unknown category: ${candidateCat}`;
  }
} catch (err) {
  parseError = `Malformed JSON from LLM: ${err.message}`;
}

return [
  {
    json: {
      ...inputMeta,
      category: parsedCategory,
      language: parsedLanguage,
      needs_retry: parsedCategory === 'unknown',
      raw_ai_output: rawContent,
      parse_error: parseError
    }
  }
];

