const userId = String($('Extract & Validate Input').item.json.user_id);
const allRows = $input.all().map(i => i.json);

const userTickets = allRows
  .filter(row => String(row.user_id) === userId)
  .slice(-5)
  .reverse();

let replyText = '';
if (userTickets.length === 0) {
  replyText = '📭 You do not have any logged support tickets yet.';
} else {
  const lines = userTickets.map((t, idx) => {
    const dateStr = (t.timestamp || '').slice(0, 16).replace('T', ' ');
    const snippet = String(t.original_message || '').slice(0, 60);
    return `${idx + 1}. [${String(t.category || 'general').toUpperCase()}] (${dateStr} UTC)\n   "${snippet}"`;
  });
  replyText = `📋 Your Last ${userTickets.length} Support Ticket(s):\n\n${lines.join('\n\n')}`;
}

return [{ json: { reply_text: replyText } }];

